package com.campusmart.exception;
import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<Map<String,Object>>bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<Map<String,Object>>validation(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(Map.of("error","Please check the submitted fields."));}@ExceptionHandler(Exception.class)ResponseEntity<Map<String,Object>>server(Exception e){return ResponseEntity.status(500).body(Map.of("error","Something went wrong. Please try again."));}}
